// the brain dir.
func writeSingleSessionFixture(t *testing.T, now time.Time, transcript string) string {
	t.Helper()
	brainDir := t.TempDir()
	tp := "sessions/main/s1.jsonl"
	p := filepath.Join(brainDir, filepath.FromSlash(tp))
	if err := os.MkdirAll(filepath.Dir(p), 0o700); err != nil {
